use std::io

fn main() {
    let mut input = ""
    let mut line = io::read_line()
    let mut lines: Vec<string> = Vec::new()
    while line.len() > 0 {
        lines.push(line.trim())
        line = io::read_line()
    }
    let limit = 200001
    let mut sieve: Vec<bool> = Vec::new()
    let mut count: Vec<int> = Vec::new()
    let mut last: Vec<int> = Vec::new()
    let mut i = 0
    while i < limit {
        sieve.push(true)
        count.push(0)
        last.push(0)
        i += 1
    }
    i = 2
    while i < limit {
        if sieve[i] {
            let mut j = i * i
            while j < limit {
                sieve[j] = false
                j += i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut l = 0
    i = 0
    while i < limit {
        if i >= 2 && sieve[i] {
            c += 1
            l = i
        }
        count[i] = c
        last[i] = l
        i += 1
    }
    let t: int = lines[0].parse().unwrap()
    let mut k = 1
    while k <= t {
        let n: int = lines[k].parse().unwrap()
        if count[n] == 0 {
            println("0 none")
        } else {
            println("{} {}", count[n], last[n])
        }
        k += 1
    }
}
